tool_calls:
mkdir -p /app/migrations; cd /app; cat > migrations/002_users_v2.sql <<'EOF'
BEGIN;

UPDATE orders SET user_id = (
  SELECT MIN(u2.id) FROM users u2
  WHERE lower(trim(u2.email)) = (SELECT lower(trim(u1.email)) FROM users u1 WHERE u1.id = orders.user_id)
)
WHERE user_id IN (SELECT id FROM users);

CREATE TABLE users_new(
  id INTEGER PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  signup_date TEXT NOT NULL
);

INSERT INTO users_new(id, first_name, last_name, email, signup_date)
SELECT id,
  CASE WHEN instr(trim(full_name), ' ') = 0 THEN trim(full_name)
       ELSE substr(trim(full_name), 1, instr(trim(full_name), ' ') - 1) END,
  CASE WHEN instr(trim(full_name), ' ') = 0 THEN ''
       ELSE trim(substr(trim(full_name), instr(trim(full_name), ' ') + 1)) END,
  lower(trim(email)),
  substr(trim(signup), 7, 4) || '-' || substr(trim(signup), 1, 2) || '-' || substr(trim(signup), 4, 2)
FROM users u
WHERE id = (SELECT MIN(id) FROM users u2 WHERE lower(trim(u2.email)) = lower(trim(u.email)));

DROP TABLE users;
ALTER TABLE users_new RENAME TO users;

UPDATE meta SET value = '2' WHERE key = 'schema_version';

COMMIT;
EOF
sqlite3 app.db < migrations/002_users_v2.sql; sqlite3 app.db "select * from users; select * from orders; select * from meta; .schema users"

